        if(cmdFifo_io_pop_valid) begin
          if(cmdFifo_io_pop_payload_write) begin
            if(when_CacheToMigAdapter_l92) begin
              io_app_wdf_end = 1'b1;
            end
          end
        end
      end
      CacheToMigAdapterState_ISSUE_READ : begin
      end
      default : begin
      end
    endcase
  end

  always @(*) begin
    cmdFifo_io_pop_ready = 1'b0;
    case(state)
      CacheToMigAdapterState_IDLE : begin
        if(cmdFifo_io_pop_valid) begin
          if(cmdFifo_io_pop_payload_write) begin
            if(when_CacheToMigAdapter_l92) begin
              cmdFifo_io_pop_ready = 1'b1;
            end
          end else begin
            cmdFifo_io_pop_ready = 1'b1;
          end
        end
      end
      CacheToMigAdapterState_ISSUE_READ : begin
      end
      default : begin
      end
    endcase
  end

  assign when_CacheToMigAdapter_l92 = ((io_app_rdy && io_app_wdf_rdy) && rspFifo_io_push_ready);
  always @(*) begin
    _zz_io_app_addr_1 = cmdFifo_io_pop_payload_addr;
    _zz_io_app_addr_1[3 : 0] = 4'b0000;
  end

  assign when_CacheToMigAdapter_l123 = (! readDataCaptured);
  assign io_busy = (state != CacheToMigAdapterState_IDLE);
  assign io_debugState = {1'd0, _zz_io_debugState};
  always @(posedge clk or posedge reset) begin
    if(reset) begin
      state <= CacheToMigAdapterState_IDLE;
      readDataCaptured <= 1'b0;
      readDataReg <= 128'h0;
    end else begin
      case(state)
        CacheToMigAdapterState_IDLE : begin
          readDataCaptured <= 1'b0;
          if(cmdFifo_io_pop_valid) begin
            if(!cmdFifo_io_pop_payload_write) begin
              state <= CacheToMigAdapterState_ISSUE_READ;
            end
          end
        end
        CacheToMigAdapterState_ISSUE_READ : begin
          if(io_app_rdy) begin
            state <= CacheToMigAdapterState_WAIT_READ;
          end
        end
        default : begin
          if(when_CacheToMigAdapter_l123) begin
            if(io_app_rd_data_valid) begin
              if(rspFifo_io_push_ready) begin
                state <= CacheToMigAdapterState_IDLE;
              end else begin
                readDataReg <= io_app_rd_data;
                readDataCaptured <= 1'b1;
              end
            end
          end else begin
            if(rspFifo_io_push_ready) begin
              readDataCaptured <= 1'b0;
              state <= CacheToMigAdapterState_IDLE;
            end
          end
        end
      endcase
    end
  end

  always @(posedge clk) begin
    case(state)
      CacheToMigAdapterState_IDLE : begin
        if(cmdFifo_io_pop_valid) begin
          if(!cmdFifo_io_pop_payload_write) begin
            activeCmd_addr <= cmdFifo_io_pop_payload_addr;
            activeCmd_write <= cmdFifo_io_pop_payload_write;
            activeCmd_wdata <= cmdFifo_io_pop_payload_wdata;
            activeCmd_wmask <= cmdFifo_io_pop_payload_wmask;
          end
        end
      end
      CacheToMigAdapterState_ISSUE_READ : begin
      end
      default : begin
      end
    endcase
  end


endmodule

